CREATE COLUMN TABLE "TEST_AP"."OTQA" ("CheckID" INTEGER CS_INT, "ObjType" NVARCHAR(20), "DocEntry" INTEGER CS_INT, "DocLineNum" INTEGER CS_INT, "SchdLine" INTEGER CS_INT, "TQAType" SMALLINT CS_INT, "ItemCode" NVARCHAR(50), "WhsCode" NVARCHAR(8), "CfmDate" LONGDATE CS_LONGDATE, "CfmQty" DECIMAL(21,6) CS_FIXED, "ReqQty" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("CheckID", "ObjType", "DocEntry", "DocLineNum", "SchdLine", "TQAType")) UNLOAD PRIORITY 5  AUTO MERGE  WITH PARAMETERS ('SESSION_TYPE'='HISTORY')